window.docContents[85].resolve({"/Onboarding___-Human-Context-Protocols/L3-___-The-body-opens-up/#A-Property-Kind-Calculus-for-Metrology___-proving-quantity-and-unit-laws-in-Lean___-from-ISO___IEC-80000-to-measurement-uncertainty--Onboarding___-Human-Context-Protocols--L3-___-The-body-opens-up--Synopsis--Errors-prevented":{"contents":"* Sum or midpoint instead of weighted mean: body A's centre of mass computed as the sum or the midpoint of its halves' positions (HCP.L3_TheBodyOpens#center_of_mass_mean).* Degenerate whole: a centre of mass reported for a body with zero total mass, which PhysLib returns as the origin (HCP.L3_TheBodyOpens#massless_center_of_mass).* Wrong frame: PhysLib accepts the lab-frame ω in the body-frame energy; with InFrame, it fails to type-check (HCP.L3_TheBodyOpens#bare_frame_mismatch, HCP.L3_TheBodyOpens#framed_rotational_energy).\n\n","context":"A Property Kind Calculus for Metrology: proving quantity and unit laws in Lean, from ISO/IEC 80000 to measurement uncertainty\u0009Onboarding: Human Context Protocols\u0009L3 — The body opens up\u0009Synopsis","header":"5.4.1.4. Errors prevented","id":"/Onboarding___-Human-Context-Protocols/L3-___-The-body-opens-up/#A-Property-Kind-Calculus-for-Metrology___-proving-quantity-and-unit-laws-in-Lean___-from-ISO___IEC-80000-to-measurement-uncertainty--Onboarding___-Human-Context-Protocols--L3-___-The-body-opens-up--Synopsis--Errors-prevented"}});